import { data, takaro } from '@takaro/helpers';

async function main() {
    const { gameServerId, player, pog, module } = data;

    // Get saved home location
    const homeVars = await takaro.variable.variableControllerSearch({
        filters: {
            key: ['home_location'],
            playerId: [player.id],
            moduleId: [module.moduleId],
            gameServerId: [gameServerId]
        }
    });

    if (homeVars.data.data.length === 0) {
        await takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
            message: "You haven't set a home location yet. Use !sethome first."
        });
        return;
    }

    const position = JSON.parse(homeVars.data.data[0].value);

    // Use teleportplayer command (same as !visit)
    await takaro.gameserver.gameServerControllerExecuteCommand(gameServerId, {
        command: `teleportplayer ${player.name} ${position.x} ${position.y} ${position.z}`
    });

    await takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
        message: `Teleporting to home... (X: ${Math.round(position.x)}, Y: ${Math.round(position.y)}, Z: ${Math.round(position.z)})`
    });
}

await main();

import { data, takaro } from '@takaro/helpers';

async function main() {
    const { gameServerId, player, pog, module } = data;

    // Use position from Takaro's polling (no command needed!)
    const position = {
        x: pog.positionX,
        y: pog.positionY,
        z: pog.positionZ || 0
    };

    if (!position.x && !position.y) {
        await takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
            message: "Unable to get your position. Try again in a few seconds."
        });
        return;
    }

    const existingVars = await takaro.variable.variableControllerSearch({
        filters: {
            key: ['home_location'],
            playerId: [player.id],
            moduleId: [module.moduleId],
            gameServerId: [gameServerId]
        }
    });

    if (existingVars.data.data.length > 0) {
        await takaro.variable.variableControllerUpdate(existingVars.data.data[0].id, {
            value: JSON.stringify(position)
        });
    } else {
        await takaro.variable.variableControllerCreate({
            key: 'home_location',
            value: JSON.stringify(position),
            playerId: player.id,
            moduleId: module.moduleId,
            gameServerId: gameServerId
        });
    }

    await takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
        message: `Home set at X: ${Math.round(position.x)}, Y: ${Math.round(position.y)}${position.z ? `, Z: ${Math.round(position.z)}` : ''}`
    });
}

await main();

import { data, takaro } from '@takaro/helpers';

async function main() {
    const { gameServerId, player, chatMessage, trigger } = data;

    // Extract target player name from chat message
    const messageText = typeof chatMessage === 'string' ? chatMessage : (chatMessage.msg || chatMessage.message || '');
    const match = messageText.match(new RegExp(`^!${trigger}\\s+(.*)`, 'i'));
    const targetPlayerName = match[1].trim();

    // Find target player
    const playersResult = await takaro.playerOnGameserver.playerOnGameServerControllerSearch({
        filters: { gameServerId: [gameServerId], online: [true] },
        extend: ['player']
    });

    const targetPog = playersResult.data.data.find(pog =>
        pog.player.name.toLowerCase() === targetPlayerName.toLowerCase()
    );

    // Teleport to target player
    await takaro.gameserver.gameServerControllerExecuteCommand(gameServerId, {
        command: `teleportplayer ${player.steamId} ${targetPog.player.steamId}`
    });

    await takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
        message: `Teleporting ${player.name} to ${targetPog.player.name}...`
    });
}

await main();
